"""Circle equations determined by a radius, a point, a diameter, or centres on an axis."""
import argparse
import json
from fractions import Fraction as F
from itertools import product
from math import sqrt
from coordinate_actions import show
from coordinate_curves import graph, curve_lesson
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/circle-equations.json'


def number(x):
    return str(F(x)).replace('-','−')


def norm(p,c):
    return sum((x-y)**2 for x,y in zip(p,c,strict=True))


def equation(center,q):
    def term(axis,a):
        if not a:return axis+'²'
        return f'({axis}{"−" if a>0 else "+"}{number(abs(a))})²'
    return term('x',center[0])+'+'+term('y',center[1])+'='+number(q)


def equation_inputs(c,q):
    s=equation(c,q);a=s.split('=',1)[0]
    numeric=[f'{number(c[0])};{number(c[1])};{number(q)}',f'{number(c[0])}; {number(c[1])}; {number(q)}']
    rhs=[number(q)]
    if q==F(1,4):rhs.extend(['0,25','0.25','¼'])
    if q==F(25,4):rhs.extend(['6,25','6.25','25/4'])
    # The prompt provides both a compact, unambiguous coefficient form and the textbook notation.
    out=[]
    for check in rhs:
        for power,around in product(('²','^2','**2'),('',' ')):
            out.append(a.replace('²',power)+around+'='+around+check)
    return list(dict.fromkeys([s]+numeric+out))


def chart(label,centers,points=None,segments=()):
    # All native circles share the same coordinate units; extra loci are added after frame construction.
    vertices=dict(points or {});radii=[]
    for j,(name,c,q) in enumerate(centers):
        vertices[name]=c;r=sqrt(q)
        for axis,v in enumerate([(c[0]+r,c[1]),(c[0]-r,c[1]),(c[0],c[1]+r),(c[0],c[1]-r)]):
            vertices['_radius'+str(j)+'p'+str(axis)]=v
        radii.append((c,q))
    frame,aliases,circle,highlights=graph(label,vertices,edges=segments)
    aliases={k:'='.join(name for name in label.split('=') if not name.startswith('_')) for k,label in aliases.items()}
    return (frame,{k:v for k,v in aliases.items() if v},circle,highlights),radii


def make(n,*,frames,cases,**data):
    card=curve_lesson(n,pages=[264],frames=[g for g,curves in frames],cases=[g for g,curves in cases],**data)
    model=card['visualization']['model']
    for i,((_,circle_specs),view) in enumerate(zip(frames+cases,model['views'].values(),strict=True)):
        suffix=f'__v{i}';raw=model['points'];o=raw['O'+suffix];scale=raw['_unitX'+suffix][0]-o[0]
        def lookup(pos):
            target=(o[0]+pos[0]*scale,o[1]+pos[1]*scale)
            options=[k for k,p in raw.items() if k.endswith(suffix) and max(abs(p[a]-target[a]) for a in (0,1))<.001]
            return min(options,key=lambda k:(k.startswith('_'),len(k),k))
        view['circles']=[]
        for j,(c,q) in enumerate(circle_specs):
            through=f'_equationRadius{j}'+suffix
            raw[through]=[o[0]+(c[0]+sqrt(q))*scale,o[1]+c[1]*scale,0]
            view['circles'].append({'center':lookup(c),'through':through})
    card['review']['reviewer']='Атанасян 7–9, 2023; печатная с. 264, ответы с. 398. Проверены исходные точки, диаметры, обе допустимые окружности №1056 и равенство радиусов №1057.'
    return card


def final_equation(card,c,q):
    card['answer']=dict(mode='exact',accepted=equation_inputs(c,q),prompt='Впиши уравнение в стандартном виде без пробелов, как (x−a)²+(y−b)²=q. Можно заменить ² на ^2 или ввести a;b;q.',feedback='Проверь знаки внутри скобок: координаты центра должны обнулять обе разности. Справа стоит квадрат радиуса.')
    return card


def origin_radii():
    p=(0,0);qs=[9,2,F(25,4)];radii='3, √2 и 5/2'
    frames=[chart('Общий центр и три возможных радиуса',[],{'S':p}),chart('Целый радиус и его квадрат',[('S',p,9)],{'T':(3,0)},[('S','T')]),chart('Три концентрические окружности',[('S',p,q) for q in qs]),chart('Новая окружность через узел сетки',[('S',p,13)],{'T':(2,3)},[('S','T')])]
    card=make(1051,question=f'Запиши уравнения трёх окружностей с центром в начале координат при радиусах {radii} в указанном порядке. У каждой окружности проверь правую часть.',answer='У левой части x²+y² во всех трёх случаях одинаковый центр. Правые части равны 9, 2 и 25/4. Уравнения: x²+y²=9, x²+y²=2 и x²+y²=25/4.',hint='В уравнение входит r². Для 5/2 возведи в квадрат и числитель, и знаменатель.',
        steps=[('Укажи центр','Обе координаты центра нулевые, поэтому сдвигов внутри квадратов нет. Левая часть каждого уравнения равна x²+y².','Изменение радиуса при неизменном центре меняет только правую часть.'),('Возведи каждый радиус в квадрат','3²=9, (√2)²=2, (5/2)²=25/4. На рисунке окружность радиуса 3 самая большая, а радиуса √2 — самая маленькая.','Слева один и тот же квадрат расстояния, справа по порядку разные константы.'),('Проверь новый радиус','Если окружность с тем же центром проходит через (2;3), то r²=4+9=13, так что её уравнение x²+y²=13.','Значение правой части можно найти по любой известной точке окружности.')],frames=frames,cases=frames[1:],prompts=[('Какое число стоит справа для радиуса √2?','2','Квадрат арифметического квадратного корня возвращает подкоренное число.'),('На новом рисунке чему равен квадрат радиуса по точке (2;3)?','13','Направление радиуса неважно: нужны 2²+3².')]);
    card['answer']=dict(mode='exact',accepted=['9;2;25/4','9; 2; 25/4','9;2;6,25','9; 2; 6,25','9;2;6.25','x²+y²=9; x²+y²=2; x²+y²=25/4','x^2+y^2=9; x^2+y^2=2; x^2+y^2=25/4'],prompt='Заверши три уравнения x²+y²=q. Введи три правые части в порядке радиусов через точку с запятой.',feedback='Вычисли отдельно 3², (√2)² и (5/2)². В последнем квадрат относится также к знаменателю.')
    return card


def known_radius():
    rows=[]
    for part,c,r,other,rr in [('а',(0,5),3,(-2,2),2),('б',(-1,2),2,(1,-3),3),('в',(-3,-7),F(1,2),(-1,-2),F(3,2)),('г',(4,-3),10,(3,1),5)]:
        q=r*r;newq=rr*rr;T=(c[0]+r,c[1]);U=(other[0],other[1]+rr)
        bare=chart('Поставь центр на сетку',[],{'A':c});rad=chart('Отметь горизонтальный радиус',[],{'A':c,'T':T},[('A','T')]);circ=chart('Проверь окружность через T',[('A',c,q)],{'T':T},[('A','T')]);other_view=chart('Изменённые центр и радиус',[('A',other,newq)],{'U':U},[('A','U')])
        card=make(1052,part=part,question=f'Запиши уравнение окружности с центром A={show(c)} и радиусом {number(r)}. Отметь точку на радиусе и проверь ответ подстановкой.',answer=f'{equation(c,q)}. В центре обе разности нулевые, а в точке T={show(T)} сумма квадратов равна {number(q)}.',hint='Используй (x−a)²+(y−b)²=r². Знаки в скобках определяются вычитанием координат A.',steps=[('Перенеси центр в формулу',f'Первая разность равна x−({c[0]}), вторая y−({c[1]}). В точке A обе равны нулю.','Центр задаёт сдвиг двух квадратов.'),('Вычисли правую часть',f'Радиус {number(r)} даёт квадрат {number(q)}. Поэтому {equation(c,q)}. При подстановке T={show(T)} одна разность равна радиусу, другая — нулю.','Правая часть уравнения равна квадрату заданной длины.'),('Составь уравнение с новыми данными',f'В новом рисунке центр {show(other)}, радиус {number(rr)}. Получается {equation(other,newq)}. Верхняя точка U имеет ординату {number(U[1])}.','Проверь как сдвиг центра, так и изменение правой части.')],frames=[bare,rad,circ,other_view],cases=[rad,circ,other_view],prompts=[('Чему равна ордината исходного центра?',str(c[1]),'Бери вторую координату точки A со знаком.'),('Каково значение правой части нового уравнения?',str(newq),f'Возведи новый радиус {number(rr)} в квадрат.')]);rows.append(final_equation(card,c,q))
    return rows


def given_point(n,c,p,other,probe):
    q=norm(p,c);newq=norm(probe,other);start=chart('Центр и заданная точка',[],{'A':c,'B':p});rad=chart('Радиус к заданной точке',[],{'A':c,'B':p},[('A','B')]);circle=chart('Окружность, проходящая через B',[('A',c,q)],{'B':p},[('A','B')]);variant=chart('Новая окружность через точку T',[('A',other,newq)],{'T':probe},[('A','T')]);
    dx,dy=(p[i]-c[i] for i in (0,1));card=make(n,question=f'Для окружности с центром {"в начале координат" if n==1053 else "A="+show(c)} известна точка B={show(p)}. Напиши уравнение окружности, вычислив правую часть по B.',answer=f'{equation(c,q)}. Квадрат радиуса равен ({dx})²+({dy})²={q}.',hint='Радиус равен расстоянию от указанного центра до B. Удобнее сразу найти его квадрат.',steps=[('Вычти координаты центра',f'От центра {show(c)} до B={show(p)} смещение ({dx};{dy}). Сдвиги вычисляем из координат B вычитанием координат центра.','Квадрат длины вектора равен сумме квадратов координат.'),('Получи полное уравнение',f'Квадрат радиуса равен {dx*dx}+{dy*dy}={q}. Подставляем центр и правую часть: {equation(c,q)}. Точка B удовлетворяет равенству.','Точка на окружности определяет радиус, если известен центр.'),('Проверь другой центр и другую точку',f'Теперь центр {show(other)}, точка T={show(probe)}. Квадрат расстояния равен {newq}, уравнение {equation(other,newq)}.','Повторяй вычисление смещения, когда изменились данные.')],frames=[start,rad,circle,variant],cases=[rad,circle,variant],prompts=[('Каков квадрат радиуса исходной окружности?',str(q),'Сложи квадраты обеих разностей координат.'),('Чему равен квадрат радиуса в новом примере?',str(newq),'Вычти новый центр из координат T, затем возведи в квадрат и сложи.')]);return final_equation(card,c,q)


def diameters():
    rows=[]
    for part,m,n,newm,newn in [('а',(-3,5),(7,-3),(-4,1),(2,5)),('б',(2,-1),(4,3),(-1,-2),(5,0))]:
        c=tuple((a+b)//2 for a,b in zip(m,n,strict=True));q=norm(m,c);other=tuple((a+b)//2 for a,b in zip(newm,newn,strict=True));newq=norm(newm,other)
        initial=chart('Диаметр по его концам',[],{'M':m,'N':n},[('M','N')]);mid=chart('Середина делит диаметр пополам',[],{'M':m,'N':n,'S':c},[('M','S'),('S','N')]);circle=chart('Оба конца лежат на окружности',[('S',c,q)],{'M':m,'N':n},[('M','N')]);variant=chart('Измени концы диаметра',[('S',other,newq)],{'M':newm,'N':newn},[('M','N')]);card=make(1055,part=part,question=f'Концы диаметра окружности M={show(m)} и N={show(n)}. Найди центр и уравнение. Проверь, что обе исходные точки лежат на найденной окружности.',answer=f'Середина диаметра S={show(c)}, квадрат радиуса {q}. Получаем {equation(c,q)}.',hint='Сначала найди средние арифметические координат концов. К радиусу относится половина диаметра, а к квадрату радиуса — четверть квадрата диаметра.',steps=[('Найди середину',f'Складываем соответствующие координаты M и N и делим каждую сумму на 2. Получаем S={show(c)}.','Центр окружности — середина любого диаметра.'),('Найди квадрат радиуса и уравнение',f'SM²=SN²={q}. Можно проверить по всему диаметру: MN²={4*q}, и его следует разделить на 4. Получаем {equation(c,q)}.','Удвоение длины увеличивает её квадрат в четыре раза.'),('Смени диаметр',f'У новых концов {show(newm)} и {show(newn)} середина {show(other)}. Квадрат расстояния от середины до каждого конца равен {newq}, поэтому {equation(other,newq)}.','При изменении концов нужно пересчитать и центр, и радиус.')],frames=[initial,mid,circle,variant],cases=[mid,circle,variant],prompts=[('Чему равна абсцисса центра исходной окружности?',str(c[0]),'Сложи абсциссы M и N и раздели сумму на два.'),('Для нового диаметра чему равен квадрат радиуса?',str(newq),'Найди середину нового диаметра, затем квадрат расстояния от неё до одного конца.')]);rows.append(final_equation(card,c,q))
    return rows


def on_horizontal_axis():
    a=(1,3);left=(-3,0);right=(5,0);low=chart('Заданная точка и ось возможных центров',[],{'A':a,'H':(1,0)},[('A','H')]);first=chart('Проверь центр слева',[('L',left,25)],{'A':a,'H':(1,0)},[('L','H'),('H','A'),('A','L')]);both=chart('Обе окружности проходят через A',[('L',left,25),('R',right,25)],{'A':a},[('L','A'),('R','A')]);new=chart('Единственный новый центр',[('S',(2,0),16)],{'T':(2,4)},[('S','T')]);
    card=make(1056,question='Окружность радиуса 5 проходит через A=(1;3). Её центр лежит на оси абсцисс. Найди все такие окружности, запиши уравнения и обоснуй число ответов.',answer='Центр имеет вид (a;0). Из (1−a)²+9=25 следуют 1−a=4 или 1−a=−4. Получены центры (−3;0) и (5;0), уравнения (x+3)²+y²=25 и (x−5)²+y²=25. Других центров нет.',hint='Координата центра, лежащего на Ox, — это (a;0). Уравнение для горизонтального смещения имеет два знака.',steps=[('Оставь одну неизвестную','Положим S=(a;0). Из SA=5 следует (1−a)²+(3−0)²=25, значит (1−a)²=16. На рисунке высота от A до оси равна 3.','Вторая координата любой точки оси Ox нулевая.'),('Сохрани два положения','Горизонтальное расстояние от (1;0) равно 4: можно двигаться вправо или влево. Получаем центры (5;0) и (−3;0). У каждой окружности радиус 5, обе содержат A. Уравнения: (x−5)²+y²=25, (x+3)²+y²=25.','После извлечения корня из положительного квадрата необходимо учесть оба знака.'),('Проверь предельный случай','Если T=(2;4), радиус 4, а центр остаётся на Ox, то весь радиус расходуется на вертикальное смещение. Получается (2−a)²=0 и единственный центр (2;0). Если расстояние от T до оси больше радиуса, центров нет.','Число центров зависит от расстояния заданной точки до оси и от радиуса.')],frames=[low,first,both,new],cases=[first,both,new],prompts=[('В исходной задаче чему равен квадрат горизонтального смещения от A до центра?','16','Из 5² вычти квадрат вертикальной разности 3.'),('Сколько новых окружностей проходит через T=(2;4) при r=4 и центре на Ox?','1','Горизонтальное смещение здесь обязательно равно нулю.')]);
    card['answer']=dict(mode='exact',accepted=['-3;5','5;-3','-3; 5','5; -3','(x+3)²+y²=25; (x−5)²+y²=25','(x−5)²+y²=25; (x+3)²+y²=25','(x+3)^2+y^2=25; (x-5)^2+y^2=25','(x-5)^2+y^2=25; (x+3)^2+y^2=25'],prompt='Заверши оба уравнения (x−a)²+y²=25. Введи через точку с запятой обе абсциссы центров. Порядок свободный.',feedback='Проверь оба корня (1−a)²=16. Абсцисса центра получается на 4 меньше или на 4 больше единицы.');return card


def on_vertical_axis():
    a=(-3,0);b=(0,9);c=(0,4);m=(-4,0);n=(0,8);t=(0,3)
    init=chart('Две заданные точки и ось возможных центров',[],{'A':a,'B':b},[('A','B')]);radii=chart('Приравняй расстояния до A и B',[],{'A':a,'B':b,'S':c},[('S','A'),('S','B')]);both=chart('Окружность, содержащая обе точки',[('S',c,25)],{'A':a,'B':b},[('S','A'),('S','B')]);new=chart('Проверь новый центр на той же оси',[('S',t,25)],{'M':m,'N':n},[('S','M'),('S','N')]);
    card=make(1057,question='Окружность проходит через A=(−3;0) и B=(0;9), а её центр лежит на оси ординат. Запиши уравнение окружности и объясни, почему центр определён однозначно.',answer='Пусть S=(0;b). Из равенства SA²=SB² выходит 9+b²=(9−b)². После сокращения b² имеем 18b=72, значит b=4. Квадрат радиуса 25, поэтому x²+(y−4)²=25.',hint='Не считай середину AB центром окружности: AB не задан как диаметр. Центр на Oy удобно записать (0;b), а затем приравнять квадраты двух радиусов.',steps=[('Запиши равенство радиусов','Для S=(0;b) получаются SA²=(−3)²+(−b)²=9+b² и SB²=(9−b)². Обе точки должны оказаться на одной окружности с этим центром.','Все точки одной окружности равноудалены от её центра.'),('Найди центр и проверь уравнение','9+b²=81−18b+b², поэтому 18b=72 и b=4. Квадрат SB равен (9−4)²=25; для A тоже выходит 9+16=25. Уравнение x²+(y−4)²=25, а единственный корень линейного равенства гарантирует единственность центра.','При вычитании равных квадратов остаётся линейное уравнение.'),('Измени обе заданные точки','Для M=(−4;0) и N=(0;8) при центре (0;t) получаем 16+t²=(8−t)². Равенство 16t=48 даёт t=3. Обе точки лежат на новой окружности x²+(y−3)²=25.','Сначала находи положение центра, затем величину радиуса.')],frames=[init,radii,both,new],cases=[radii,both,new],prompts=[('Чему равна ордината исходного центра после сокращения 18b=72?','4','Раздели обе части на 18.'),('При новых M и N найди ординату центра на Oy.','3','Раскрой (8−t)², сократи t² и реши 16t=48.')]);return final_equation(card,c,25)


def build():
    return {'bookId':BOOK,'lessons':[origin_radii()]+known_radius()+[given_point(1053,(0,0),(-1,3),(1,-1),(3,2)),given_point(1054,(0,6),(-3,2),(-2,1),(1,5))]+diameters()+[on_horizontal_axis(),on_vertical_axis()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args()
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert OUT.read_text()==text
    else:OUT.write_text(text)
